def parse_duration(text):
    """Parse strings like '1h30m', '45s' or '2h' into seconds."""
    units = {"h": 3600, "m": 60, "s": 1}
    total = 0
    number = ""
    for char in text.strip().lower():
        if char.isdigit():
            number += char
        elif char in units:
            total += int(number) * units[char]
            number = ""
        else:
            raise ValueError(f"bad character: {char}")
    if number:
        total += int(number)
    return total
```

